-- Strict v2 references must still resolve in the transaction that publishes a batch.
-- Generated schema change is 0007; this manual guard changes no existing facts.
CREATE TRIGGER operating_material_reference_guard BEFORE INSERT ON business_facts
WHEN (SELECT template_version FROM ingestion_batches WHERE id=NEW.batch_id)='2'
